    'threat-analysis' => 'fixtures/eval-threat-stats-v1.json',
];
const BLOTTER_ASSIST_DENYLIST = ['guilty', 'liable', 'must pay', 'penalty', 'settlement', 'sentenced'];
const SMS_DENYLIST = ['regards', 'sincerely', 'sent by', 'signed,', '- barangay'];

$options = parseArguments($argv);
$task = $options['task'];
if ($task === 'redaction' && !in_array($options['engine'], ['baseline', 'model'], true)) {
    out("Unknown engine '{$options['engine']}' — use baseline or model.");
    exit(1);
}
if ($task !== 'redaction' && $options['engine'] === 'baseline') {
    out("--engine=baseline only applies to --task=redaction (no baseline exists for {$task}) — using the model.");
}
$engine = $task === 'redaction' ? $options['engine'] : 'model';

$datasetPath = $options['dataset'] ?? TASK_DEFAULTS[$task];
if (!str_starts_with($datasetPath, '/') && !preg_match('/^[A-Za-z]:/', $datasetPath)) {
    $datasetPath = dirname(__DIR__) . '/' . ltrim($datasetPath, '/');
}
if (!is_file($datasetPath)) {
    out("Dataset not found: {$datasetPath}");
    exit(1);
}

$raw = file_get_contents($datasetPath);
$dataset = json_decode((string) $raw, true);
if (!is_array($dataset)) {
    out("Dataset is not valid JSON: {$datasetPath}");
    exit(1);
}

$records = $dataset['records'] ?? $dataset;
$datasetName = is_array($dataset) && isset($dataset['dataset_name']) ? (string) $dataset['dataset_name'] : basename($datasetPath, '.json');
$datasetVersion = is_array($dataset) && isset($dataset['dataset_version']) ? (string) $dataset['dataset_version'] : 'v1';

if (!is_array($records) || $records === []) {
    out('Dataset contains no records.');
    exit(1);
}
if ($options['limit'] !== null) {
    $records = array_slice($records, 0, $options['limit']);
}

$client = null;
$modelVersion = 'baseline:regex';
if ($engine === 'model') {
    $client = new OllamaClient();
    if (!$client->isConfigured()) {
        out('Ollama is not configured — set OLLAMA_URL and OLLAMA_MODEL, or use --task=redaction --engine=baseline.');
        exit(1);
    }
    $modelVersion = $client->model();
}

out(sprintf(
    'Baranguard AI evaluation — task=%s engine=%s dataset=%s (%s) records=%d',
    $task, $engine, $datasetName, $datasetVersion, count($records)
));
if ($engine === 'model') {
    out("Model: {$modelVersion} · prompts: " . AiPrompts::PROMPT_VERSION);
    out('This calls the model once per record and is SLOW on CPU. --limit=N to sample.');
}
if ($task === 'translation') {
    out("Translating to: {$options['translateTo']} — placeholder-preservation checked mechanically only; adequacy needs a human bilingual rater (see this file's own header).");
}

// --- Checkpoint (--resume) ---------------------------------------------
$checkpointPath = checkpointPath($datasetPath, $task, $engine, $modelVersion);
$checkpointRecords = [];
if ($options['resume'] && is_file($checkpointPath)) {
    $loaded = json_decode((string) file_get_contents($checkpointPath), true);
    if (is_array($loaded)
        && ($loaded['dataset'] ?? null) === $datasetName
        && ($loaded['dataset_version'] ?? null) === $datasetVersion
        && ($loaded['task'] ?? null) === $task
        && ($loaded['engine'] ?? null) === $engine
        && ($loaded['model_version'] ?? null) === $modelVersion
        && is_array($loaded['records'] ?? null)
    ) {
        $checkpointRecords = $loaded['records'];
        out(sprintf('Resuming: %d record(s) already scored in a previous run of this exact dataset/task/engine/model.', count($checkpointRecords)));
    } else {
        out('A checkpoint file exists but is for a different dataset/task/engine/model — starting fresh (old checkpoint left untouched).');
    }
}
if ($options['resume'] || $options['batchSize'] !== null) {
    out("Checkpoint file: {$checkpointPath}");
}
out('');

$totals = newTotals($task);
$scored = 0;
$skipped = 0;
$resumedFromCheckpoint = 0;
$verboseLog = [];
$startedAt = microtime(true);
$sinceLastRest = 0;

foreach ($records as $index => $record) {
    if (!is_array($record)) {
        $skipped++;
        continue;
    }
    $id = (string) ($record['id'] ?? ('record-' . $index));

    if (isset($checkpointRecords[$id])) {
        foldResult($task, $totals, $checkpointRecords[$id]);
        $scored++;
        $resumedFromCheckpoint++;
        continue;
    }

    $prompt = buildPrompt($task, $record, $options['translateTo']);
    if ($prompt === null) {
        $skipped++;
        continue;
    }

    try {
        $output = $task === 'redaction' && $engine === 'baseline'
            ? RegexRedactor::redact((string) $record['narrative'])
            : AiPrompts::stripReasoning($client->generate($prompt)['text']);
    } catch (OllamaUnavailableException $e) {
        out("[{$id}] Ollama unavailable — stopping. Nothing was written.");
        out('  ' . $e->getMessage());
        out('Progress so far is safely checkpointed — rerun the same command with --resume to continue.');
        exit(1);
    } catch (OllamaException $e) {
        out("[{$id}] model error, scoring as a full miss: " . $e->getMessage());
        $output = '';
    }

    $result = scoreOne($task, $record, $output);
    foldResult($task, $totals, $result);
    $scored++;

    if ($options['verbose'] || recordFailedSomething($task, $result)) {
        $line = formatRecordLine($task, $id, $result);
        out($line);
        $verboseLog[] = $line;
    }

    $checkpointRecords[$id] = $result;
    writeCheckpoint($checkpointPath, $datasetName, $datasetVersion, $task, $engine, $modelVersion, $checkpointRecords);

    if ($options['batchSize'] !== null) {
        $sinceLastRest++;
        $recordsRemaining = count($records) - $scored - $skipped;
        if ($sinceLastRest >= $options['batchSize'] && $recordsRemaining > 0) {
            out(sprintf('--- resting %ds after %d records (batch pacing) ---', $options['restSeconds'], $sinceLastRest));
            sleep($options['restSeconds']);
            $sinceLastRest = 0;
        }
    }
}

if ($resumedFromCheckpoint > 0) {
    out(sprintf('(%d of %d records were already scored from the checkpoint and were not re-run.)', $resumedFromCheckpoint, $scored));
}

$elapsed = round(microtime(true) - $startedAt, 1);
$metrics = finalizeMetrics($task, $totals, $scored);

$resultLines = [
    '================ RESULT ================',
    "Task:        {$task}",
    "Engine:      {$engine} ({$modelVersion})",
    "Dataset:     {$datasetName} ({$datasetVersion})",
    "Records:     {$scored} scored" . ($skipped > 0 ? ", {$skipped} skipped (malformed/not applicable)" : ''),
];
foreach ($metrics['lines'] as $line) {
    $resultLines[] = $line;
}
$resultLines[] = "Elapsed:     {$elapsed}s";
$resultLines[] = '========================================';
if (isset($metrics['meetsTarget'])) {
    $resultLines[] = $metrics['meetsTarget'] ? 'MEETS its provisional target.' : 'DOES NOT meet its provisional target.';
}

out('');
