    'metricAName' => $metrics['metricAName'] ?? null,
    'metricAValue' => $metrics['metricAValue'] ?? null,
    'metricBName' => $metrics['metricBName'] ?? null,
    'metricBValue' => $metrics['metricBValue'] ?? null,
]);

out('');
out("Recorded in ai_evaluation_run (task={$task}, dataset={$datasetName} {$datasetVersion}, model_version={$modelVersion}).");
exit(0);

// =========================================================================
// --- Per-task input building, scoring, and aggregation ------------------
// =========================================================================

function buildPrompt(string $task, array $record, string $translateTo): ?string
{
    switch ($task) {
        case 'redaction':
            if (!isset($record['narrative'])) {
                return null;
            }
            return AiPrompts::redaction((string) $record['narrative']);
        case 'extraction':
            if (!isset($record['narrative'])) {
                return null;
            }
            return AiPrompts::extraction((string) $record['narrative']);
        case 'summary':
            if (!isset($record['narrative'])) {
                return null;
            }
            return AiPrompts::summary(RedactionScorer::deriveGoldRedacted((string) $record['narrative'], $record['entities'] ?? []));
        case 'translation':
            if (!isset($record['narrative'])) {
                return null;
            }
            return AiPrompts::translation(RedactionScorer::deriveGoldRedacted((string) $record['narrative'], $record['entities'] ?? []), $translateTo);
        case 'blotter-assist':
            if (!isset($record['narrative'])) {
                return null;
            }
            return AiPrompts::blotterAssist((string) $record['narrative'], (string) ($record['incident_type'] ?? 'other'));
        case 'classification':
            if (!isset($record['narrative'])) {
                return null;
            }
            $goldRedacted = RedactionScorer::deriveGoldRedacted((string) $record['narrative'], $record['entities'] ?? []);
            return AiPrompts::classification($goldRedacted, (string) ($record['incident_type'] ?? ''), (string) ($record['priority'] ?? ''));
        case 'sms-compose':
            if (!isset($record['prompt'])) {
                return null;
            }
            return AiPrompts::smsCompose((string) $record['prompt']);
        case 'threat-analysis':
            if (!isset($record['aggregate_summary'])) {
                return null;
            }
            return AiPrompts::threatAnalysis((string) $record['aggregate_summary'], (string) ($record['period_label'] ?? 'the recorded period'));
        default:
            return null;
    }
}

function scoreOne(string $task, array $record, string $output): array
{
    switch ($task) {
        case 'redaction':
            return RedactionScorer::score((string) $record['narrative'], $output, $record['entities'] ?? [], $record['must_keep'] ?? []);

        case 'extraction':
            return ExtractionScorer::score(
                (string) ($record['complainant'] ?? ''),
                (string) ($record['respondent'] ?? ''),
                (string) ($record['contact'] ?? ''),
                $output
            );

        case 'classification':
            return ClassificationScorer::score((string) ($record['incident_type'] ?? ''), (string) ($record['priority'] ?? ''), $output);

        case 'summary': {
            $goldRedacted = RedactionScorer::deriveGoldRedacted((string) $record['narrative'], $record['entities'] ?? []);
            $checks = [
                'placeholders_preserved' => ChecklistScorer::placeholderCountsMatch($goldRedacted, $output),
                'length_2_to_4_sentences' => ChecklistScorer::sentenceCountInRange($output, 2, 4),
            ];
            return ChecklistScorer::summarize($checks);
        }

        case 'translation': {
            $goldRedacted = RedactionScorer::deriveGoldRedacted((string) $record['narrative'], $record['entities'] ?? []);
            $checks = ['placeholders_preserved' => ChecklistScorer::placeholderCountsMatch($goldRedacted, $output)];
            return ChecklistScorer::summarize($checks);
        }

        case 'blotter-assist': {
            $entityTexts = array_map(static fn ($e) => is_array($e) ? (string) ($e['text'] ?? '') : (string) $e, $record['entities'] ?? []);
            $leaks = RedactionScorer::countLeaks($output, $entityTexts);
            $checks = [
                'no_pii_leaked' => $leaks['leakCount'] === 0,
                'length_3_to_6_sentences' => ChecklistScorer::sentenceCountInRange($output, 3, 6),
                'no_legal_conclusion_language' => ChecklistScorer::noDenylistTerms($output, BLOTTER_ASSIST_DENYLIST),
            ];
            $summary = ChecklistScorer::summarize($checks);
            $summary['leaked'] = $leaks['leaked'];
            return $summary;
        }

        case 'sms-compose': {
            $decoy = $record['planted_pii'] ?? null;
            $leaks = $decoy !== null ? RedactionScorer::countLeaks($output, [(string) $decoy]) : ['leakCount' => 0, 'leaked' => []];
            $checks = [
                'within_300_chars' => ChecklistScorer::charCountAtMost($output, 300),
                'no_planted_pii_leaked' => $leaks['leakCount'] === 0,
                'no_signature' => ChecklistScorer::noDenylistTerms($output, SMS_DENYLIST),
                'mentions_given_facts' => ChecklistScorer::mentionsAllFacts($output, $record['given_facts'] ?? []),
            ];
            $summary = ChecklistScorer::summarize($checks);
            $summary['leaked'] = $leaks['leaked'];
            return $summary;
        }

        case 'threat-analysis': {
            $grounding = ChecklistScorer::numbersAreGrounded($output, $record['counts'] ?? []);
            $checks = [
                'has_both_section_headers' => ChecklistScorer::containsAllHeaders($output, ['Patterns:', 'Suggested patrols:']),
                'numbers_grounded_in_input' => $grounding['ok'],
                'at_most_3_patrol_suggestions' => ChecklistScorer::bulletCount(
                    substr($output, (int) max(0, mb_stripos($output, 'Suggested patrols:')))
                ) <= 3,
            ];
            $summary = ChecklistScorer::summarize($checks);
            $summary['fabricated'] = $grounding['fabricated'];
            return $summary;
        }

        default:
            return [];
    }
}

function newTotals(string $task): array
{
    return match ($task) {
        'redaction' => ['tp' => 0, 'fn' => 0, 'fp' => 0],
        'extraction' => ['complainant' => 0, 'respondent' => 0, 'contact' => 0],
        'classification' => ['typeMatch' => 0, 'priorityMatch' => 0],
        default => ['passed' => 0, 'total' => 0], // every checklist-scored task
    };
}

function foldResult(string $task, array &$totals, array $result): void
{
    switch ($task) {
        case 'redaction':
            $totals['tp'] += $result['tp'] ?? 0;
            $totals['fn'] += $result['fn'] ?? 0;
            $totals['fp'] += $result['fp'] ?? 0;
            break;
        case 'extraction':
            $totals['complainant'] += ($result['complainant'] ?? false) ? 1 : 0;
            $totals['respondent'] += ($result['respondent'] ?? false) ? 1 : 0;
            $totals['contact'] += ($result['contact'] ?? false) ? 1 : 0;
            break;
        case 'classification':
            $totals['typeMatch'] += ($result['typeMatch'] ?? false) ? 1 : 0;
            $totals['priorityMatch'] += ($result['priorityMatch'] ?? false) ? 1 : 0;
            break;
        default:
            $totals['passed'] += $result['passed'] ?? 0;
            $totals['total'] += $result['total'] ?? 0;
            break;
    }
}

function recordFailedSomething(string $task, array $result): bool
{
    return match ($task) {
        'redaction' => ($result['fn'] ?? 0) > 0,
        'extraction' => !($result['complainant'] ?? true) || !($result['respondent'] ?? true) || !($result['contact'] ?? true),
        'classification' => !($result['typeMatch'] ?? true) || !($result['priorityMatch'] ?? true),
        default => ($result['failed'] ?? []) !== [],
    };
}

function formatRecordLine(string $task, string $id, array $result): string
{
    return match ($task) {
        'redaction' => sprintf('[%s] tp=%d fn=%d fp=%d%s', $id, $result['tp'], $result['fn'], $result['fp'], $result['leaked'] === [] ? '' : ' LEAKED: ' . implode(' | ', $result['leaked'])),
        'extraction' => sprintf('[%s] complainant=%s respondent=%s contact=%s', $id, $result['complainant'] ? 'ok' : 'MISS', $result['respondent'] ? 'ok' : 'MISS', $result['contact'] ? 'ok' : 'MISS'),
        'classification' => sprintf('[%s] type=%s priority=%s', $id, $result['typeMatch'] ? 'ok' : 'MISS', $result['priorityMatch'] ? 'ok' : 'MISS'),
        default => sprintf('[%s] %d/%d checks passed%s', $id, $result['passed'] ?? 0, $result['total'] ?? 0, ($result['failed'] ?? []) === [] ? '' : ' FAILED: ' . implode(', ', $result['failed'])),
    };
}

function formatScore(?float $value): string
{
    return $value === null ? 'n/a (no applicable records)' : sprintf('%.2f%%', $value * 100);
}

/** @return array{lines:string[],notes:string,meetsTarget?:bool,precisionScore?:?float,recallScore?:?float,metricAName?:?string,metricAValue?:?float,metricBName?:?string,metricBValue?:?float} */
function finalizeMetrics(string $task, array $totals, int $scored): array
{
    switch ($task) {
        case 'redaction': {
            $recall = ($totals['tp'] + $totals['fn']) > 0 ? $totals['tp'] / ($totals['tp'] + $totals['fn']) : null;
            $precision = ($totals['tp'] + $totals['fp']) > 0 ? $totals['tp'] / ($totals['tp'] + $totals['fp']) : null;
            return [
                'lines' => [
                    "Entities:    TP={$totals['tp']} FN={$totals['fn']} FP={$totals['fp']}",
                    'Recall:      ' . formatScore($recall) . '   (target >= 95%)',
                    'Precision:   ' . formatScore($precision) . '   (target >= 90%)',
                ],
                'notes' => "tp={$totals['tp']} fn={$totals['fn']} fp={$totals['fp']}",
                'meetsTarget' => $recall !== null && $precision !== null ? ($recall >= 0.95 && $precision >= 0.90) : null,
                'precisionScore' => $precision, 'recallScore' => $recall,
            ];
        }
        case 'extraction': {
            $comp = $scored > 0 ? $totals['complainant'] / $scored : null;
            $resp = $scored > 0 ? $totals['respondent'] / $scored : null;
            $cont = $scored > 0 ? $totals['contact'] / $scored : null;
            $overall = ($comp !== null && $resp !== null && $cont !== null) ? ($comp + $resp + $cont) / 3 : null;
            return [
                'lines' => [
                    'Complainant accuracy: ' . formatScore($comp) . '   (provisional target >= 85%)',
                    'Respondent accuracy:  ' . formatScore($resp) . '   (provisional target >= 85%)',
                    'Contact accuracy:     ' . formatScore($cont) . '   (provisional target >= 85%)',
                ],
                'notes' => sprintf('complainant=%.4f respondent=%.4f contact=%.4f', $comp ?? -1, $resp ?? -1, $cont ?? -1),
                'meetsTarget' => $comp !== null ? ($comp >= 0.85 && $resp >= 0.85 && $cont >= 0.85) : null,
                'metricAName' => 'complainant_accuracy', 'metricAValue' => $comp,
                'metricBName' => 'overall_field_accuracy', 'metricBValue' => $overall,
            ];
        }
        case 'classification': {
            $typeAcc = $scored > 0 ? $totals['typeMatch'] / $scored : null;
            $prioAcc = $scored > 0 ? $totals['priorityMatch'] / $scored : null;
            return [
                'lines' => [
                    'Type accuracy:     ' . formatScore($typeAcc) . '   (provisional target >= 85%)',
                    'Priority accuracy: ' . formatScore($prioAcc) . '   (provisional target >= 80%)',
                ],
                'notes' => sprintf('type_accuracy=%.4f priority_accuracy=%.4f', $typeAcc ?? -1, $prioAcc ?? -1),
                'meetsTarget' => $typeAcc !== null ? ($typeAcc >= 0.85 && $prioAcc >= 0.80) : null,
                'metricAName' => 'type_accuracy', 'metricAValue' => $typeAcc,
                'metricBName' => 'priority_accuracy', 'metricBValue' => $prioAcc,
            ];
        }
        default: { // every ChecklistScorer-based task: summary, translation, blotter-assist, sms-compose, threat-analysis
            $rate = $totals['total'] > 0 ? $totals['passed'] / $totals['total'] : null;
            $label = $task === 'translation' ? 'Placeholder-preservation rate' : 'Mechanical compliance rate';
            $target = $task === 'translation' ? null : 0.90;
            return [
                'lines' => array_filter([
                    "{$label}: " . formatScore($rate) . ($target !== null ? '   (provisional target >= 90%)' : ''),
                    $task === 'translation' ? 'NOTE: adequacy/fluency needs a human bilingual rater — not computed by this script.' : null,
                ]),
                'notes' => sprintf('%s=%.4f (%d/%d checks)', $task === 'translation' ? 'placeholder_rate' : 'compliance_rate', $rate ?? -1, $totals['passed'], $totals['total']),
                'meetsTarget' => $target !== null && $rate !== null ? $rate >= $target : null,
                'metricAName' => $task === 'translation' ? 'placeholder_preservation_rate' : 'mechanical_compliance_rate',
                'metricAValue' => $rate,
            ];
        }
    }
}

// =========================================================================
// --- CLI / checkpoint plumbing (unchanged in shape from the original) --
// =========================================================================

/**
 * @param string[] $argv
 */
function parseArguments(array $argv): array
{
    $options = [
        'task' => 'redaction',
        'engine' => 'baseline',
        'translateTo' => 'fil',
        'dataset' => null,
        'limit' => null,
        'dryRun' => false,
        'verbose' => false,
        'batchSize' => null,
        'restSeconds' => 60,
        'resume' => false,
        'saveResults' => false,
    ];
    foreach (array_slice($argv, 1) as $argument) {
        if (str_starts_with($argument, '--task=')) {
            $value = substr($argument, strlen('--task='));
            if (!array_key_exists($value, TASK_DEFAULTS)) {
                out("Unknown task '{$value}' — use one of: " . implode(', ', array_keys(TASK_DEFAULTS)));
                exit(1);
            }
            $options['task'] = $value;
        } elseif (str_starts_with($argument, '--engine=')) {
            $options['engine'] = substr($argument, strlen('--engine='));
        } elseif (str_starts_with($argument, '--translate-to=')) {
            $options['translateTo'] = substr($argument, strlen('--translate-to='));
        } elseif (str_starts_with($argument, '--dataset=')) {
            $options['dataset'] = substr($argument, strlen('--dataset='));
        } elseif (str_starts_with($argument, '--limit=')) {
            $options['limit'] = max(1, (int) substr($argument, strlen('--limit=')));
        } elseif ($argument === '--dry-run') {
            $options['dryRun'] = true;
        } elseif ($argument === '--verbose') {
            $options['verbose'] = true;
        } elseif (str_starts_with($argument, '--batch-size=')) {
            $options['batchSize'] = max(1, (int) substr($argument, strlen('--batch-size=')));
        } elseif (str_starts_with($argument, '--rest-seconds=')) {
            $options['restSeconds'] = max(0, (int) substr($argument, strlen('--rest-seconds=')));
        } elseif ($argument === '--resume') {
            $options['resume'] = true;
        } elseif ($argument === '--save-results') {
            $options['saveResults'] = true;
        }
    }
    return $options;
}

/**
 * One checkpoint file per (dataset, task, engine, model) combination,
 * next to the dataset itself.
 */
function checkpointPath(string $datasetPath, string $task, string $engine, string $modelVersion): string
{
    $slug = preg_replace('/[^A-Za-z0-9]+/', '_', $modelVersion) ?? 'model';
    $base = pathinfo($datasetPath, PATHINFO_FILENAME);
    return dirname($datasetPath) . "/{$base}.{$task}.{$engine}.{$slug}.checkpoint.json";
}

function writeCheckpoint(string $path, string $datasetName, string $datasetVersion, string $task, string $engine, string $modelVersion, array $records): void
{
    file_put_contents($path, json_encode([
        'dataset' => $datasetName,
        'dataset_version' => $datasetVersion,
        'task' => $task,
        'engine' => $engine,
        'model_version' => $modelVersion,
        'updated_at' => gmdate('c'),
        'records' => $records,
    ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
}

function out(string $message): void
{
    fwrite(STDOUT, $message . PHP_EOL);
}
